/* Bubblegum Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="bubblegum-light"] {
  --background: rgb(246, 230, 238);
  --foreground: rgb(91, 91, 91);
  --card: rgb(253, 237, 201);
  --card-foreground: rgb(91, 91, 91);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(91, 91, 91);
  --primary: rgb(208, 79, 153);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(138, 207, 209);
  --secondary-foreground: rgb(51, 51, 51);
  --muted: rgb(178, 225, 235);
  --muted-foreground: rgb(122, 122, 122);
  --accent: rgb(251, 226, 167);
  --accent-foreground: rgb(51, 51, 51);
  --destructive: rgb(249, 111, 112);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(208, 79, 153);
  --input: rgb(228, 228, 228);
  --ring: rgb(230, 112, 171);
  --chart-1: rgb(230, 112, 171);
  --chart-2: rgb(132, 210, 226);
  --chart-3: rgb(251, 226, 167);
  --chart-4: rgb(243, 160, 202);
  --chart-5: rgb(215, 72, 142);
  --radius: 0.4rem;
  --sidebar: rgb(245, 215, 232);
  --sidebar-foreground: rgb(51, 51, 51);
  --sidebar-primary: rgb(237, 75, 154);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(248, 167, 211);
  --sidebar-accent-foreground: rgb(51, 51, 51);
  --sidebar-border: rgb(244, 234, 255);
  --sidebar-ring: rgb(237, 75, 154);
  --font-sans: Poppins, sans-serif;
  --font-serif: Lora, serif;
  --font-mono: Fira Code, monospace;
  --shadow-color: rgba(209, 81, 154, 0.5);
  --shadow-opacity: 1;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 3px;
  --shadow-offset-y: 3px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 3px 3px 0px 0px hsl(325.78 58.18% 56.86% / 0.5);
  --shadow-xs: 3px 3px 0px 0px hsl(325.78 58.18% 56.86% / 0.5);
  --shadow-sm:
    3px 3px 0px 0px hsl(325.78 58.18% 56.86% / 1),
    3px 1px 2px -1px hsl(325.78 58.18% 56.86% / 1);
  --shadow:
    3px 3px 0px 0px hsl(325.78 58.18% 56.86% / 1),
    3px 1px 2px -1px hsl(325.78 58.18% 56.86% / 1);
  --shadow-md:
    3px 3px 0px 0px hsl(325.78 58.18% 56.86% / 1),
    3px 2px 4px -1px hsl(325.78 58.18% 56.86% / 1);
  --shadow-lg:
    3px 3px 0px 0px hsl(325.78 58.18% 56.86% / 1),
    3px 4px 6px -1px hsl(325.78 58.18% 56.86% / 1);
  --shadow-xl:
    3px 3px 0px 0px hsl(325.78 58.18% 56.86% / 1),
    3px 8px 10px -1px hsl(325.78 58.18% 56.86% / 1);
  --shadow-2xl: 3px 3px 0px 0px hsl(325.78 58.18% 56.86% / 2.5);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="bubblegum-dark"] {
  --background: rgb(18, 36, 46);
  --foreground: rgb(243, 227, 234);
  --card: rgb(28, 46, 56);
  --card-foreground: rgb(243, 227, 234);
  --popover: rgb(28, 46, 56);
  --popover-foreground: rgb(243, 227, 234);
  --primary: rgb(251, 226, 167);
  --primary-foreground: rgb(18, 36, 46);
  --secondary: rgb(228, 162, 177);
  --secondary-foreground: rgb(18, 36, 46);
  --muted: rgb(35, 39, 43);
  --muted-foreground: rgb(228, 162, 177);
  --accent: rgb(199, 123, 150);
  --accent-foreground: rgb(243, 227, 234);
  --destructive: rgb(227, 94, 164);
  --destructive-foreground: rgb(18, 36, 46);
  --border: rgb(50, 72, 89);
  --input: rgb(32, 51, 61);
  --ring: rgb(80, 175, 182);
  --chart-1: rgb(80, 175, 182);
  --chart-2: rgb(228, 162, 177);
  --chart-3: rgb(199, 123, 150);
  --chart-4: rgb(23, 92, 108);
  --chart-5: rgb(35, 39, 43);
  --radius: 0.4rem;
  --sidebar: rgb(14, 31, 41);
  --sidebar-foreground: rgb(245, 245, 245);
  --sidebar-primary: rgb(237, 75, 154);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(248, 167, 211);
  --sidebar-accent-foreground: rgb(31, 41, 56);
  --sidebar-border: rgb(54, 64, 80);
  --sidebar-ring: rgb(237, 75, 154);
  --font-sans: Poppins, sans-serif;
  --font-serif: Lora, serif;
  --font-mono: Fira Code, monospace;
  --shadow-color: rgb(50, 72, 89);
  --shadow-opacity: 1;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 3px;
  --shadow-offset-y: 3px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 3px 3px 0px 0px hsl(206.15 28.06% 27.25% / 0.5);
  --shadow-xs: 3px 3px 0px 0px hsl(206.15 28.06% 27.25% / 0.5);
  --shadow-sm:
    3px 3px 0px 0px hsl(206.15 28.06% 27.25% / 1),
    3px 1px 2px -1px hsl(206.15 28.06% 27.25% / 1);
  --shadow:
    3px 3px 0px 0px hsl(206.15 28.06% 27.25% / 1),
    3px 1px 2px -1px hsl(206.15 28.06% 27.25% / 1);
  --shadow-md:
    3px 3px 0px 0px hsl(206.15 28.06% 27.25% / 1),
    3px 2px 4px -1px hsl(206.15 28.06% 27.25% / 1);
  --shadow-lg:
    3px 3px 0px 0px hsl(206.15 28.06% 27.25% / 1),
    3px 4px 6px -1px hsl(206.15 28.06% 27.25% / 1);
  --shadow-xl:
    3px 3px 0px 0px hsl(206.15 28.06% 27.25% / 1),
    3px 8px 10px -1px hsl(206.15 28.06% 27.25% / 1);
  --shadow-2xl: 3px 3px 0px 0px hsl(206.15 28.06% 27.25% / 2.5);
}
